create table ecommerce_data (
customer_id varchar(30),
customer_name varchar(100),
customer_age numeric(5,2),
gender varchar(20),
country varchar(50),
account_creation_date date,
customer_segment varchar(50),
total_orders numeric(10,2),
total_spending_usd numeric(12,2),
preferred_category varchar(100)
);
--1. Find the total number of customers in top 10 country.
select country,count(customer_id) as total_customer
from ecommerce_data
group by country
order by count(customer_id) desc
limit 10;
--2.Calculate the total revenue generated by top 5 country and sort it in descending order.
select country,round(sum(total_spending_usd),0) as total_revenue_usd
from ecommerce_data
group by country
order by sum(total_spending_usd) desc
limit 5;
--3.Find the  top 5 most popular preferred product category based on the number of customers.
select preferred_category,count(customer_name) as total_customers
from ecommerce_data
group by preferred_category
order by count(customer_name) desc
limit 5;
--4.Find customers whose total spending is greater than the overall average spending.
select customer_name,total_spending_usd 
from ecommerce_data
where total_spending_usd > (select avg(total_spending_usd) from ecommerce_data)
order by total_spending_usd desc;
--5.Find the gender-wise customer count and percentage.
select gender,count(customer_id) as total_customers
,round(count(customer_id)*100/(select count(*) from ecommerce_data),2) as
total_percentage
from ecommerce_data
group by gender
order by total_customers desc;
--6. top 5 Rank customers based on their total spending
select customer_name,total_spending_usd, 
rank() over(order by total_spending_usd desc) 
as customer_rank
from ecommerce_data
limit 5;
order by total_customers desc;
--7. count of customer segment orders wise
select customer_segment,count(*) as total_order
from ecommerce_data
group by customer_segment
order by total_order desc;
select * from ecommerce_data;